    /** Maximum number of owners permitted per city. */
    static final int CAPACITY = 50;

    /**
     * Lowest per-city owner count at which a {@code capacityWarning} is raised (inclusive); the city is
     * "approaching capacity" once it holds this many owners but is not yet {@link #CAPACITY full}.
     */
    static final int WARNING_THRESHOLD = 40;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        if (countInCity(city, ownerRepository) >= CAPACITY) {
            throw new CityAtCapacityException(city, CAPACITY);
        }
    }

    /**
     * Counts the owners whose city matches {@code city} in its {@link OwnerCity#normalize normalized}
     * form — the single source of the per-city owner count shared by the capacity check and the
     * {@link FlagCityCapacityWarning capacity warning}.
     */
    static int countInCity(String city, OwnerRepository ownerRepository) {
        String normalizedCity = OwnerCity.normalize(city);
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (normalizedCity.equals(OwnerCity.normalize(existing.getCity()))) {
                count++;
            }
        }
        return count;
    }
}

